export const LANGUAGES = [
  { value: 'en', label: 'English', locale: 'en-IN' },
  { value: 'hi', label: 'हिन्दी', locale: 'hi-IN' },
  { value: 'mr', label: 'मराठी', locale: 'mr-IN' },
  { value: 'gu', label: 'ગુજરાતી', locale: 'gu-IN' },
  { value: 'ta', label: 'தமிழ்', locale: 'ta-IN' },
  { value: 'te', label: 'తెలుగు', locale: 'te-IN' },
  { value: 'kn', label: 'ಕನ್ನಡ', locale: 'kn-IN' },
];
export function detectLanguage() {
  try {
    const saved = localStorage.getItem('reloop-language');
    if (saved && LANGUAGES.some(x => x.value === saved)) return saved;
  } catch {}
  const code = (typeof navigator !== 'undefined' ? navigator.language : 'en').toLowerCase().split('-')[0];
  return LANGUAGES.some(x => x.value === code) ? code : 'en';
}
export function languageLocale(lang) { return LANGUAGES.find(x => x.value === lang)?.locale || 'en-IN'; }
