export function t(value, lang) {
  let language = lang;
  if (!language) { try { language = localStorage.getItem('reloop-language') || 'en'; } catch { language = 'en'; } }
  const translated = base[language]?.[value];
  if (language !== 'en' && !translated && typeof import.meta !== 'undefined' && import.meta.env?.DEV) {
    // Development-only telemetry: make fallback-to-English visible to developers.
    try {
      const key = `reloop-i18n-missing:${language}`;
      const missing = JSON.parse(sessionStorage.getItem(key) || '[]');
      if (!missing.includes(value)) {
        missing.push(value);
        sessionStorage.setItem(key, JSON.stringify(missing));
        console.warn(`[ReLoop i18n] Missing ${language} translation:`, value);
      }
    } catch {}
  }
  return translated || value;
}

export function getTranslationAudit(keys) {
  const uniqueKeys = [...new Set(keys)].sort();
  const locales = Object.fromEntries(LANGUAGES.map(({ value }) => {
    const missing = uniqueKeys.filter(key => value !== 'en' && !base[value]?.[key]);
    return [value, { total: uniqueKeys.length, translated: uniqueKeys.length - missing.length, missing }];
  }));
  return { totalKeys: uniqueKeys.length, locales };
}

