for (const [language, entries] of Object.entries(feedbackTranslations)) Object.assign(base[language], entries);

export function translateMessage(message, lang) {
  if (typeof message !== 'string') return message;
  const exact = base[lang]?.[message];
  if (exact) return exact;
  const issueUpdate = message.match(/^Issue (.+) updated\.$/);
  if (issueUpdate) return `${t('Issue updated.', lang)} (${issueUpdate[1]})`;
  const issueRecorded = message.match(/^Issue (.+) recorded on the shared workspace\.$/);
  if (issueRecorded) return `${t('Issue recorded on the shared workspace.', lang)} (${issueRecorded[1]})`;
  const issueDemo = message.match(/^Issue (.+) recorded in this browser demo\.$/);
  if (issueDemo) return `${t('Issue recorded in this browser demo.', lang)} (${issueDemo[1]})`;
  const offerAccepted = message.match(/^Offer accepted\. (.+) has been selected\.$/);
  if (offerAccepted) return `${t('Offer accepted.', lang)} ${offerAccepted[1]} ${t('has been selected.', lang)}`;
  const partner = message.match(/^Partner marked (verified|rejected)\.$/);
  if (partner) return t(`Partner marked ${partner[1]}.`, lang);
  const switched = message.match(/^Switched to (.+) workspace$/);
  if (switched) return `${t('Switched to workspace', lang)}: ${t(switched[1], lang)}`;
  const offerStatus = message.match(/^Offer (accepted|declined|pending)\.$/);
  if (offerStatus) return t(`Offer ${offerStatus[1]}.`, lang);
  return message;
}

